import { useTranslation } from 'react-i18next';
import { ChevronDown } from 'lucide-react';
import { useState, useRef, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  rtlLanguages, supportedLanguages, changeLanguage,
  LANGUAGE_META, stripLocalePrefix,
} from '../i18n/config';
import { localizePath } from '../i18n/paths';
import { pathArticleLanguages } from '../content';

// supportedLanguages is already "listed in LANGUAGE_META and has translation
// files on disk", so a language reaches this menu only when it is genuinely
// shipped. A half-translated locale in the repo is never offered to visitors.
const languages = supportedLanguages.map((code) => ({ code, ...LANGUAGE_META[code] }));

export default function LanguageSwitcher() {
  const { t, i18n } = useTranslation('edb');
  const navigate = useNavigate();
  const { pathname } = useLocation();
  // On an article, only the languages it is published in (content/translations.json):
  // the site has no page for the others, so offering them would lead nowhere.
  const pageLanguages = pathArticleLanguages(stripLocalePrefix(pathname));
  const offered = pageLanguages ? languages.filter((lang) => pageLanguages.includes(lang.code)) : languages;
  const isRTL = rtlLanguages.includes(i18n.language);
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLanguageChange = async (newLang) => {
    setIsOpen(false);
    if (i18n.language === newLang) return;

    const { pathname, search, hash } = window.location;
    const target = localizePath(stripLocalePrefix(pathname), newLang) + search + hash;
    if (typeof window !== 'undefined' && typeof window.gtag !== 'undefined') {
      window.gtag('event', 'language_change', {
        event_category: 'user_preference',
        event_label: newLang
      });
    }
    // The inlined homepage bundle only carries English: load the real page.
    if (import.meta.env.EDB_HOME) {
      window.location.assign(target);
      return;
    }

    await changeLanguage(newLang);

    // Strip any existing locale prefix off the current path, then re-prefix
    // for the target language, keeping search/hash so deep links round-trip.
    navigate(target);
  };

  const currentLanguage = languages.find((lang) => lang.code === i18n.language) || languages[0];

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setIsOpen((v) => !v)}
        className={`site-control-button flex items-center justify-center gap-1 pt-2.5 pb-2.5 h-10 ${isRTL ? 'pr-2.5 pl-1' : 'pl-2.5 pr-1'}`}
        aria-label={t('languageSwitcher.ariaLabel')}
      >
        <span className="text-lg">{currentLanguage.flag}</span>
        <ChevronDown className={`w-2.5 h-2.5 text-slate-600 dark:text-slate-400 transition-transform duration-200 ${isRTL ? 'ml-1' : 'mr-1'} ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {/* max-h + scroll because this list grew from 2 entries to a dozen;
          without it the menu runs off the bottom of a short viewport. */}
      {isOpen && (
        <div className={`language-menu absolute mt-2 w-44 max-h-[70vh] overflow-y-auto z-50 ${isRTL ? 'left-0' : 'right-0'}`}>
          {offered.map((lang) => (
            <button
              key={lang.code}
              onClick={() => handleLanguageChange(lang.code)}
              className={`w-full flex items-center gap-3 px-4 py-2.5 hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors duration-200 ${
                i18n.language === lang.code ? 'bg-sky-50 dark:bg-sky-900/20' : ''
              }`}
            >
              <span className="text-lg">{lang.flag}</span>
              <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{lang.name}</span>
              {i18n.language === lang.code && (
                <span className={`${isRTL ? 'mr-auto' : 'ml-auto'} w-2 h-2 bg-sky-600 dark:bg-sky-400 rounded-full`}></span>
              )}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
